import {FACTIONS,TILES,PLANETS,TECHS,OBJECTIVES,SECRETS,ACTION_CATALOGUE,STRATEGIES,UNIT_TYPES,UNIT_NAMES,LIMITS,IMPLEMENTED_FACTIONS,FACTION_HELP,TECH_HELP,RULES_URL} from './data.js';
import {createGame,transact,decision,ownedPlanets,available,unit,spaceUnits,capacity,productionLimit,buildCost,unitsOf,fleetLimit,canResearch,objectiveEligible,neighborPlayers,name,initiativeOrder} from './engine.js?v=0.1.1';
import {aiAction,chooseTech} from './ai.js?v=0.1.1';
import {renderGalaxy,mountGalaxy} from './map.js';
import {HELP,guidance} from './help.js';
import {saveLocal,readLocal,slots,exportSave,importSave} from './storage.js';
const app=document.querySelector('#app'),dialog=document.querySelector('#dialog');let game=null,view='galaxy',selected='0,0',empire=0,map=null,camera=null,autoAI=true,aiTimer=null,aiError='',history=[],toastTimer;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const data=x=>esc(JSON.stringify(x));
const button=(text,action,args={},cls='')=>`<button type="button" class="btn ${cls}" data-action="${action}" data-args="${data(args)}">${text}</button>`;
const help=id=>`<button type="button" class="help" data-help="${id}" aria-label="Help: ${esc(HELP[id]?.[0]||id)}" title="${esc(HELP[id]?.[0]||id)}">?</button>`;
const title=(text,id)=>`${text}${help(id)}`;
const panel=(heading,id,body,tag='')=>`<section class="panel"><div class="panelhead"><h2>${title(heading,id)}</h2>${tag?`<span class="tag">${tag}</span>`:''}</div><div class="body">${body}</div></section>`;
const options=(items,current)=>items.map(([v,t])=>`<option value="${esc(v)}" ${String(v)===String(current)?'selected':''}>${esc(t)}</option>`).join('');
const field=(label,html,id)=>`<label class="field"><span>${label}${id?help(id):''}</span>${html}</label>`;
const number=(key,value=0,max=99,min=0)=>`<input type="number" name="${key}" value="${value}" min="${min}" max="${max}" step="1" inputmode="numeric" required>`;
const select=(key,items,current)=>`<select name="${key}">${options(items,current)}</select>`;
const check=(key,value,text,checked=false,sub='')=>`<label class="check"><input type="checkbox" name="${key}" value="${esc(value)}" ${checked?'checked':''}><span class="copy">${esc(text)}${sub?`<small>${esc(sub)}</small>`:''}</span></label>`;
const planetChoices=(p,empty=false)=>(empty?[['','None']]:[]).concat(ownedPlanets(game,p).map(x=>[x.id,PLANETS[x.id].name]));
const tabs=[['galaxy','◎','Galaxy'],['operations','↗','Operations'],['empire','♜','Empire'],['objectives','◇','Objectives'],['archive','▤','Archive']];
const brand=()=>`<div class="brand"><img src="icon.svg" alt=""><div><b>TWILIGHT IMPERIUM IV</b><small>THE SITUATION ROOM</small></div></div>`;
function short(p){return FACTIONS[game.players[p].faction].factionName.replace(/^The /,'').replace('The Universities of ','').replace('Universities of ','').replace('The Federation of ','').replace('Federation of ','').replace('Emirates of ','').replace('Barony of ','').replace(' Kingdom','').replace('Sardakk Norr',"Sardakk N’orr");}
function unitChips(units,p){const groups={};for(const u of units)groups[u.type]=(groups[u.type]||0)+1;return Object.entries(groups).map(([t,n])=>`<span class="unit-chip" style="--faction:${game.players[p].color}"><b>${n}</b>${UNIT_NAMES[t]}</span>`).join('')||'<small>No units</small>';}
function chrome(body){const d=decision(game);return`<div class="shell"><aside class="sidebar">${brand()}<div class="eyebrow" style="margin-top:38px;color:var(--muted)">Imperial command</div><nav>${tabs.map(([id,icon,text])=>`<button class="${view===id?'active':''}" data-action="view" data-args="${data({view:id})}"><b>${icon}</b>${text}</button>`).join('')}</nav><div class="sidebar-foot"><span class="cyan">● LOCAL CAMPAIGN</span><br>Solo AI · portable saves<br>Fourth Edition / base game<br>${button('Core preview · status','coverage',{},'ghost small')}</div></aside><header class="topbar">${brand()}<div class="buttons">${button('Save','saveMenu',{},'small')}${help('saves')}</div></header><main id="content">${body}</main><nav class="mobile-nav" aria-label="Main navigation">${tabs.map(([id,icon,text])=>`<button class="${view===id?'active':''}" data-action="view" data-args="${data({view:id})}" ${view===id?'aria-current="page"':''}><b>${icon}</b>${text}</button>`).join('')}</nav></div>`;}
function welcome(){const demo=createGame({seed:44,count:6}),factionSelect=IMPLEMENTED_FACTIONS.map(f=>[f,FACTIONS[f].factionName]);let saved=false;try{saved=!!readLocal();}catch{}
return`<div class="welcome"><header class="welcome-top">${brand()}${button('Implementation status','coverage',{},'ghost small')}</header><section class="welcome-hero"><div class="hero-copy"><div class="eyebrow">Fourth Edition · An unofficial browser adaptation</div><h1 style="margin-top:18px">THE GALAXY<br>AWAITS ITS<br><em>NEXT EMPEROR.</em></h1><p class="intro">Build your civilization. Command your fleets. Shape the council. The throne of Mecatol Rex is won through strategy, influence, and ambition.</p><div class="buttons">${saved?button('Resume campaign →','resume',{},'primary'):''}${button('Load save file','import',{},'ghost')}${help('saves')}</div><div class="feature-grid"><div><b>3–6</b><span>Civilizations</span></div><div><b>10 / 14</b><span>Victory points</span></div><div><b>8</b><span>Strategy cards</span></div></div></div><div class="hero-map" aria-hidden="true">${renderGalaxy(demo,{hero:true})}</div></section><section class="panel welcome-setup"><div class="body"><div class="setup-title"><div><div class="eyebrow">New campaign</div><h2>Choose your civilization</h2></div><span class="step">01</span></div><form id="new-game" class="form-stack">${field('Your faction',select('faction',factionSelect,'sol'),'reference')}<div class="fields">${field('Civilizations',select('count',[[3,'3 factions · 2 AI'],[4,'4 factions · 3 AI'],[5,'5 factions · 4 AI'],[6,'6 factions · 5 AI']],3),'ai')}${field('AI difficulty',select('difficulty',[['easy','Easy'],['normal','Normal'],['hard','Hard']],'normal'),'ai')}</div><div class="fields">${field('Victory target',select('target',[[10,'10 points · standard'],[14,'14 points · long game']],10),'objectives')}${field('Galaxy setup','<input type="text" value="Official preset" readonly aria-label="Galaxy setup">','map')}</div><div class="notice">Core-systems preview: six playable factions. Several card, faction, technology and council effects remain unfinished. ${button('View exact coverage','coverage',{},'ghost small')}</div><button class="btn primary wide" type="submit">Begin your campaign →</button></form></div></section><p class="footer-note">Unofficial fan project. Twilight Imperium belongs to Fantasy Flight Games. Original browser interface and vector artwork. Base fourth edition only; expansions are not enabled.</p></div>`;}
function header(){const p=game.players[empire],d=decision(game),g=guidance(game),who=d.player;return`<div class="pagehead"><div><div class="eyebrow">${game.players.length} civilizations / ${game.winner!==null?'Campaign concluded':'Imperial situation report'}</div><h1>${tabs.find(x=>x[0]===view)?.[2]||'Command center'}</h1><p class="smalltext" style="margin-top:5px">${short(empire)} · ${p.human?'Your civilization':game.difficulty+' AI'}</p></div><div class="round">ROUND<b>${String(game.round).padStart(2,'0')}</b>${game.winner!==null?'FINAL':game.phase.toUpperCase()}</div></div><div class="phases" aria-label="Round phases">${['strategy','action','status','agenda'].map((id,i)=>`<div class="phase ${game.phase===id?'active':''}" ${game.phase===id?'aria-current="step"':''}><i>${i+1}</i>${id[0].toUpperCase()+id.slice(1)} phase</div>`).join('')}</div><div class="factions">${game.players.map((pl,i)=>`<button class="faction ${i===empire?'current':''}" style="--faction:${pl.color}" data-action="empire" data-args="${data({player:i})}"><span class="sigil">${pl.faction.slice(0,2).toUpperCase()}</span><div><div class="name">${esc(short(i))} ${i===who&&game.winner===null?'<span class="gold">•</span>':''}</div><div class="sub">${pl.vp} / ${game.target} VP · ${pl.human?'You':'AI'}${game.speaker===i?' · Speaker':''}</div></div></button>`).join('')}</div><div class="resources"><div class="resource"><div class="label">Ready resources ${help('economy')}</div><div class="value gold">${available(game,empire)}</div><div class="sub">Ready planets + trade goods</div></div><div class="resource"><div class="label">Ready influence ${help('economy')}</div><div class="value cyan">${available(game,empire,'influence')}</div><div class="sub">Ready planets + trade goods</div></div><div class="resource"><div class="label">Trade goods ${help('trade')}</div><div class="value" style="color:var(--rose)">${p.tg}</div><div class="sub">${p.commodities} / ${FACTIONS[p.faction].commodities} commodities</div></div></div><section class="guidance"><div class="copy"><div class="eyebrow">${game.winner!==null?'The new emperor':!game.players[who].human&&game.pending?.type!=='councilResolve'?'AI decision / '+esc(short(who)):'What to do next'}</div><h2>${esc(g[0])}</h2><p>${esc(g[1])}</p></div><div class="controls">${help(g[2])}${button('Go to decision →','view',{view:'operations'},'cyan small')}</div></section>`;}
function mapPanel(){const sys=game.systems[selected]||game.systems['0,0'];return`<section class="panel galaxy-panel"><div class="panelhead"><h2>${title('Galactic theater','map')}</h2><span class="tag">${Object.keys(game.systems).length} systems</span></div><div class="map-toolbar"><select id="find-system" aria-label="Find a system"><option value="">Find a system…</option>${Object.values(game.systems).sort((a,b)=>TILES[a.tile].name.localeCompare(TILES[b.tile].name)).map(x=>`<option value="${x.key}">${x.tile} · ${esc(TILES[x.tile].name)}</option>`).join('')}</select><div class="map-actions"><button class="btn small" data-camera="out" aria-label="Zoom out">−</button><button class="btn small" data-camera="fit" aria-label="Fit whole galaxy">100%</button><button class="btn small" data-camera="in" aria-label="Zoom in">+</button><button class="btn small" data-camera="expand" aria-expanded="false">Full screen</button>${help('touch')}</div></div><div id="galaxy-viewport" class="galaxy-viewport" role="region" tabindex="0" aria-label="Interactive galaxy: tap to inspect, drag to pan, pinch to zoom"><div class="galaxy-stage">${renderGalaxy(game,{selected})}</div></div><div class="map-selection"><div class="copy"><div class="eyebrow">Selected system / ${sys.tile}</div><strong>${esc(TILES[sys.tile].name)}</strong></div>${button('Details','systemDetails',{},'small')}${help('map')}</div><div class="map-hint"><span>Drag to pan · Pinch or double tap to zoom</span>${help('touch')}</div><div class="map-legend"><span class="gold">● Resources</span><span class="cyan">● Influence</span><span>▲ Ships</span><span>Colored ring = control</span><span>Small dots = activation tokens</span></div></section>`;}
function systemInfo(){const sys=game.systems[selected];if(!sys)return'';const d=TILES[sys.tile],actor=decision(game),p=actor.player,can=game.phase==='action'&&!game.pending&&game.players[p].human;return`<div class="eyebrow">System ${sys.tile}${sys.home!==null?' / HOME SYSTEM':''}</div><h2 style="font-size:30px;margin:5px 0 15px">${esc(d.name)}</h2>${d.isGravityRift?'<div class="notice">Gravity-rift movement risk is not automated in this preview.</div>':''}<div class="list">${d.planets.map(id=>planetCard(id)).join('')||'<p class="smalltext">No planets in this system.</p>'}${[...new Set(sys.ships.map(u=>u.owner))].map(i=>`<div class="card"><div class="eyebrow" style="color:${game.players[i].color}">${esc(short(i))}</div>${unitChips(sys.ships.filter(u=>u.owner===i),i)}</div>`).join('')}</div><div class="divider"></div><div class="smalltext">Activation tokens: ${sys.tokens.length?sys.tokens.map(i=>esc(short(i))).join(', '):'none'}</div><div class="buttons" style="margin-top:14px">${can?button('Activate this system →','tactical',{system:selected},'primary'):''}${help('movement')}</div>`;}
function planetCard(id){const x=game.planets[id],d=PLANETS[id],owner=x.owner;return`<article class="card planet-card ${x.ready?'':'exhausted'}" style="--faction:${owner===null?'#53617b':game.players[owner].color}"><div class="planet-orb" aria-hidden="true"></div><div class="copy"><h3>${esc(d.name)}</h3><small>${owner===null?'Uncontrolled':esc(short(owner))+' · '+(x.ready?'Ready':'Exhausted')} · ${d.trait?.toLowerCase()||'home'}</small><div style="margin-top:5px"><small>${x.ground.length} infantry${x.pds?' · '+x.pds+' PDS':''}${x.dock?' · '+x.dock+' space dock':''}${d.specialty.length?' · ◆ '+d.specialty.map(z=>z.toLowerCase()).join(', '):''}</small></div></div><div class="stats"><span class="gold">${d.resources}</span><span class="muted"> / </span><span class="cyan">${d.influence}</span></div></article>`;}
function tokensPanel(p){const pl=game.players[p];return panel('Command sheet','tokens',`<div class="fields three">${['tactic','fleet','strategy'].map(k=>`<div><div class="eyebrow" style="color:var(--muted)">${k}</div><div class="score">${pl.tokens[k]}</div><small>${k==='fleet'?'Fleet limit: '+fleetLimit(game,p):k==='tactic'?'System activations':'Secondary abilities'}</small></div>`).join('')}</div><div class="divider"></div><div class="smalltext">${Object.values(game.systems).filter(x=>x.tokens.includes(p)).length} command tokens on the map · 16 total in the faction supply</div>`);}
function objectiveCard(id,isSecret=false,scoring=false){const ob=OBJECTIVES[id]||SECRETS[id],eligible=objectiveEligible(game,decision(game).player,id),q=game.pending,claimed=game.players.filter(x=>x.scored.includes(id)).map(x=>FACTIONS[x.faction].factionName.replace(/^The /,''));return`<article class="card objective ${isSecret?'secret':''}"><div class="row"><span class="points">${isSecret?'Secret / ':ob.points===2?'Stage II / ':'Stage I / '}${ob.points} VP</span><span class="badge">${ob.phase}</span></div><h3 style="margin-top:9px">${esc(ob.name)}</h3><p>${esc(ob.text)}</p>${claimed.length?`<small style="display:block;margin-top:9px">Scored: ${esc(claimed.join(', '))}</small>`:''}${scoring&&eligible?`<div class="buttons">${button('Score objective','score',{id,secret:isSecret},'cyan small')}</div>`:''}</article>`;}
function journal(n=10){return panel('Campaign journal','start',game.log.slice(-n).reverse().map(x=>`<div class="journal-entry"><div class="stamp">Round ${x.round} / ${esc(x.phase)}</div><p>${esc(x.text)}</p></div>`).join(''));}
function technologyRows(p){const pl=game.players[p],colors={PROPULSION:'#78c7e6',WARFARE:'#df8399',CYBERNETIC:'#d8bf78',BIOTIC:'#86b69b',UNITUPGRADE:'#b09bd9'};return pl.tech.map(id=>{const t=TECHS[id];return`<div class="tech-row" style="--tech:${colors[t.types[0]]||'#a2acc2'}"><b>${esc(t.name)}</b><small>${esc(TECH_HELP[id]||`${t.types[0]==='UNITUPGRADE'?'Unit upgrade':'Faction technology'} · some card-specific abilities remain unfinished; see coverage.`)}</small></div>`;}).join('');}
function empirePanel(){const p=empire,pl=game.players[p];return`<div class="layout equal"><div class="stack">${tokensPanel(p)}${panel('Controlled planets','economy',`<div class="list">${ownedPlanets(game,p).map(x=>planetCard(x.id)).join('')}</div>`,ownedPlanets(game,p).length+' planets')}${panel('Faction profile','reference',`<h2>${esc(FACTIONS[pl.faction].factionName)}</h2><p style="font-size:12px;margin-top:8px">${esc(FACTION_HELP[pl.faction])}</p><div class="notice" style="margin-top:14px">Selected faction abilities are automated. The full faction-specific timing and technology list remains under development.</div>`)}</div><div class="stack">${panel('Researched technologies','tech',`<div class="tech-list">${technologyRows(p)}</div>`)}${handPanel(p)}${scoreboard()}</div></div>`;}
const automatedCards=['mining_initiative','industrial_initiative','economic_initiative','f_deployment','unexpected','messiah','f_researched'];
function handPanel(p){const pl=game.players[p];if(!pl.human)return panel('Private cards','cards',`<p class="smalltext">${pl.cards.length} action cards · ${pl.secrets.length} unscored secret objectives. Opponents’ private hands remain hidden.</p>`);const playable=game.phase==='action'&&!game.pending&&game.active===p;return panel('Your action cards','cards',`<div class="list">${pl.cards.map(id=>{const c=ACTION_CATALOGUE[id],implemented=automatedCards.includes(id);return`<article class="card"><div class="row"><h3>${esc(c.name)}</h3><span class="badge">${esc(c.phase)}</span></div><p>${esc(c.window)}</p><small class="${implemented?'cyan':'warn'}">${implemented?'Automated effect':'Timing / effect not automated in this preview'}</small>${implemented&&playable?`<div class="buttons">${button('Play card','cardForm',{card:id},'small')}</div>`:''}</article>`;}).join('')||'<div class="empty">No action cards yet. Draw during status or through Politics.</div>'}</div>`);}
function scoreboard(){return panel('Imperial standing','objectives',`<div class="list">${[...game.players.keys()].sort((a,b)=>game.players[b].vp-game.players[a].vp).map(i=>`<div class="card" style="--faction:${game.players[i].color}"><div class="row"><div><h3>${esc(short(i))}</h3><small>${game.players[i].scored.length} public · ${game.players[i].secretScored.length} secret${game.winner===i?' · EMPEROR':''}</small></div><div class="score">${game.players[i].vp}<small> / ${game.target}</small></div></div><div class="progress"><i style="width:${Math.min(100,game.players[i].vp/game.target*100)}%"></i></div></div>`).join('')}</div>`);}
function objectivesPage(){return`<div class="layout equal"><div class="stack">${panel('Public objectives','objectives',`<div class="list">${game.public.map(id=>objectiveCard(id)).join('')}</div>`,game.public.length+' revealed')}${panel('Mecatol Rex','custodians',`<p class="smalltext">${game.custodians?'The custodians remain. The first landing costs 6 influence and awards 1 VP.':'The custodians token has been removed. The galactic council meets each round.'}</p>`)}</div><div class="stack">${panel('Your secret objectives','objectives',`<div class="list">${game.players[0].secrets.map(id=>objectiveCard(id,true)).join('')||'<div class="empty">No unscored secret objectives.</div>'}${game.players[0].secretScored.map(id=>`<div class="card"><span class="pill">Scored · 1 VP</span><h3 style="margin-top:8px">${esc(SECRETS[id].name)}</h3></div>`).join('')}</div>`)}${scoreboard()}</div></div>`;}
function currentOperation(){
 const d=decision(game),p=d.player,pl=game.players[p],q=game.pending,can=pl.human||q?.type==='councilResolve';let html='';
 if(game.winner!==null)return panel('Imperial throne','objectives',`<div class="eyebrow">The campaign is over</div><h2 style="font-size:33px;margin:8px 0">${esc(name(game,game.winner))}</h2><p class="smalltext">${game.players[game.winner].vp} victory points. Review the final board, or save your campaign.</p><div class="buttons" style="margin-top:16px">${button('Download campaign','export',{},'primary')}${button('New campaign','newMenu',{},'ghost')}</div>`);
 if(!can){html=`<div class="eyebrow">${esc(short(p))} / ${game.difficulty} AI</div><h2 style="font-size:28px;margin:6px 0">${autoAI&&!aiError?'Planning the next move…':'AI operations paused'}</h2><p class="smalltext">${esc(guidance(game)[0])}. Private hands stay hidden.</p>${aiError?`<div class="notice" style="margin-top:12px">AI stopped on a rules check: ${esc(aiError)}</div>`:''}<div class="buttons" style="margin-top:15px">${button(autoAI?'Pause AI':'Resume AI','autoAI',{},'cyan')}${button('Advance one decision','stepAI',{},'small')}${help('ai')}</div>`;return panel('Current decision','action',html);}
 if(q?.type==='setupSecret')html=`<p class="smalltext" style="margin-bottom:14px">Keep one objective. Your choice remains private.</p><div class="list">${game.setupSecrets[p].map(id=>`<article class="card objective secret"><div class="points">Secret / 1 VP · ${SECRETS[id].phase}</div><h3 style="margin:8px 0">${esc(SECRETS[id].name)}</h3><p>${esc(SECRETS[id].text)}</p><div class="buttons">${button('Keep this objective','engine',{type:'setupSecret',args:{card:id}},'cyan')}</div></article>`).join('')}</div>`;
 else if(q?.type==='secondary')html=`<div class="eyebrow">${esc(short(q.owner))} used ${STRATEGIES[q.card].name}</div><h2 style="margin:8px 0">Your secondary opportunity</h2><p class="smalltext">${esc(STRATEGIES[q.card].secondary)}</p><div class="buttons" style="margin-top:17px">${button('Use secondary →','strategyForm',{card:q.card,secondary:true},'primary')}${button('Decline','engine',{type:'secondary',args:{use:false}},'ghost')}</div>`;
 else if(q?.type==='invasion'){const sys=game.systems[q.system],cargo=sys.ships.filter(u=>u.owner===p&&u.type==='infantry').length;html=`<div class="eyebrow">${esc(TILES[sys.tile].name)}</div><h2 style="margin:5px 0">Invasion planning</h2><p class="smalltext">${cargo} infantry in transport. Assign landing forces to gain control of planets.</p><div class="buttons" style="margin-top:15px">${button('Plan invasion →','invasionForm',{},'primary')}${button('Skip invasion','engine',{type:'invade',args:{lands:[]}},'ghost')}</div>`;}
 else if(q?.type==='production')html=`<div class="eyebrow">${esc(TILES[game.systems[q.system].tile].name)}</div><h2 style="margin:5px 0">Production step</h2><p class="smalltext">Production limit: ${productionLimit(game,p,q.system)} units. ${available(game,p)} resources available.</p><div class="buttons" style="margin-top:15px">${productionLimit(game,p,q.system)?button('Build units →','productionForm',{},'primary'):''}${button('Finish tactical action','engine',{type:'produce',args:{}},'ghost')}</div>`;
 else if(q?.type==='combat')html=`<div class="eyebrow">${q.kind==='space'?'Space':'Ground'} combat / Round ${q.round}</div><h2 style="margin:5px 0 15px">${q.kind==='space'?esc(TILES[game.systems[q.system].tile].name):esc(PLANETS[q.planet].name)}</h2><div class="list">${[q.attacker,q.defender].map(i=>`<div class="battle-side" style="--faction:${game.players[i].color}"><div class="eyebrow" style="color:var(--faction)">${esc(short(i))} / ${q.attacker===i?'attacker':'defender'}</div>${unitChips((q.kind==='space'?game.systems[q.system].ships:game.planets[q.planet].ground).filter(x=>x.owner===i&&x.type!=='infantry'=== (q.kind==='space')),i)}</div>`).join('')}</div><div class="buttons" style="margin-top:16px">${button('Resolve next round →','combatForm',{},'primary')}${help('retreat')}</div>`;
 else if(q?.type==='hits'||q?.type==='capacity'){
  const units=(q.kind==='ground'?game.planets[q.planet].ground:game.systems[q.system].ships).filter(u=>u.owner===p&&(q.type==='capacity'?['fighter','infantry'].includes(u.type):q.kind==='ground'||u.type!=='infantry')&&(!q.fighters||u.type==='fighter')&&(!q.nonfighter||u.type!=='fighter'));
  html=`<div class="eyebrow">${q.type==='capacity'?'Transport capacity':'Incoming hits'}</div><h2 style="margin:5px 0 15px">${q.type==='capacity'?q.excess+' excess units':q.hits+' hit'+(q.hits===1?'':'s')+' to assign'}</h2><div class="list">${units.map(u=>{const v=unit(game,p,u.type),sustain=v.sustainDamage&&!u.damaged&&!q.fighters&&!q.nonfighter&&q.type!=='capacity';return`<div class="card"><div class="row"><div><h3>${UNIT_NAMES[u.type]}</h3><small>${u.damaged?'Damaged':'Undamaged'} · Combat ${v.combatHitsOn<=10?v.combatHitsOn+'+':'—'}</small></div><div class="buttons">${sustain?button('Sustain','engine',{type:'hit',args:{unit:u.id,sustain:true}},'cyan small'):''}${button(q.type==='capacity'?'Remove':'Destroy','engine',{type:q.type==='capacity'?'capacity':'hit',args:{unit:u.id}},'danger small')}</div></div></div>`;}).join('')}</div>`;
 }
 else if(q?.type==='statusScore')html=`<p class="smalltext" style="margin-bottom:13px">Score up to one public and one secret objective, then finish. Eligibility checks use your current empire.</p><div class="list">${!q.publicDone?game.public.filter(id=>objectiveEligible(game,p,id)).map(id=>objectiveCard(id,false,true)).join(''):''}${!q.secretDone?pl.secrets.filter(id=>SECRETS[id].phase==='Status'&&objectiveEligible(game,p,id)).map(id=>objectiveCard(id,true,true)).join(''):''}<div class="notice">${q.publicDone?'Public scored. ':'No public objective scored yet. '}${q.secretDone?'Secret scored.':'No secret objective scored yet.'}</div></div><div class="buttons" style="margin-top:16px">${button('Finish scoring →','engine',{type:'statusScore',args:{done:true}},'primary')}</div>`;
 else if(q?.type==='redistribute')html=`<p class="smalltext">Your status tokens have been added. Keep the same total, and leave enough fleet supply to support your fleets.</p><form id="redistribute-form" class="form-stack" style="margin-top:16px"><div class="fields three">${['tactic','fleet','strategy'].map(k=>field(k[0].toUpperCase()+k.slice(1),number(k,pl.tokens[k],16),'tokens')).join('')}</div><p class="form-note">Total available: ${Object.values(pl.tokens).reduce((a,b)=>a+b,0)} tokens.</p><div class="dialog-error"></div><button class="btn primary" type="submit">Confirm command sheet →</button></form>`;
 else if(q?.type==='discard'){const secret=q.kind==='secret',cards=pl[secret?'secrets':'cards'];html=`<p class="smalltext" style="margin-bottom:14px">${secret?'Three secret objectives, including scored objectives, is the limit.':'You may keep seven action cards.'} Choose a card to discard.</p><div class="list">${cards.map(id=>`<div class="card row"><h3>${esc((secret?SECRETS:ACTION_CATALOGUE)[id].name)}</h3>${button('Discard','engine',{type:'discard',args:{card:id}},'small')}</div>`).join('')}</div>`;}
 else if(q?.type==='extraAction')html=`<p class="smalltext">Fleet Logistics gives you the option of another action this turn.</p><div class="buttons" style="margin-top:15px">${button('Take extra action','engine',{type:'extraAction',args:{use:true}},'primary')}${button('End turn','engine',{type:'extraAction',args:{use:false}},'ghost')}</div>`;
 else if(q?.type==='agendaReveal')html=`<div class="notice">Agenda effects require assisted rules review in this first release. AI automation pauses at outcome resolution.</div><form id="agenda-reveal" class="form-stack" style="margin-top:15px">${field('Agenda title','<input type="text" name="agenda" maxlength="150" placeholder="Name of the revealed agenda" required>','council')}<button class="btn primary" type="submit">Open council voting →</button></form>`;
 else if(q?.type==='council')html=`<div class="eyebrow">Agenda ${game.agendaIndex+1} / 2</div><h2 style="margin:6px 0 14px">${esc(q.agenda)}</h2><form id="vote-form" class="form-stack">${field('Vote',select('outcome',[['for','For'],['against','Against'],['abstain','Abstain']]),'council')}<div>${ownedPlanets(game,p).filter(x=>x.ready).map(x=>check('votePlanet',x.id,PLANETS[x.id].name,false,PLANETS[x.id].influence+' influence')).join('')||'<small>No ready planets for voting.</small>'}</div><div class="dialog-error"></div><button type="submit" class="btn primary">Cast votes →</button></form>`;
 else if(q?.type==='councilResolve')html=`<div class="notice">Assisted council review: this preview tallies votes but does not enforce agenda-specific outcomes. Consult the actual agenda card and record the remaining effect. This is an unfinished system.</div><h2 style="margin-top:15px">${esc(q.agenda)}</h2><div class="list" style="margin-top:12px">${Object.entries(q.votes).map(([p,v])=>`<div class="row smalltext"><span>${esc(short(Number(p)))}</span><span>${v.votes} · ${esc(v.outcome)}</span></div>`).join('')}</div><form id="council-resolve" class="form-stack" style="margin-top:18px">${field('Rules review / outcome note','<textarea name="note" minlength="4" maxlength="2000" placeholder="Record the outcome and any unresolved effect. No effect is applied automatically." required></textarea>','council')}<div class="dialog-error"></div><button class="btn primary" type="submit">Record assisted outcome →</button></form>`;
 else if(game.phase==='strategy')html=`<div class="eyebrow">${game.speaker===p?'You are the speaker':'Clockwise selection'}</div><h2 style="margin:5px 0 14px">Choose a strategy card</h2><div class="list">${STRATEGIES.slice(1).map((c,i)=>{const id=i+1,owner=game.players.findIndex(x=>x.strategies.includes(id));return`<article class="card strategy-card" style="--strategy:${c.color}"><div class="row"><div class="row"><span class="number">${id}</span><h3>${c.name}</h3></div>${owner>=0?`<span class="badge">${esc(short(owner))}</span>`:button('Choose','engine',{type:'pick',args:{card:id}},'small')}</div><p>${esc(c.primary)}</p>${game.strategyGoods[id]?`<small class="gold">+${game.strategyGoods[id]} trade goods on this card</small>`:''}</article>`;}).join('')}</div>`;
 else if(game.phase==='action')html=`<div class="eyebrow">Your action-phase turn</div><h2 style="margin:5px 0 15px">Command your civilization</h2><div class="list"><div class="card"><h3>01 / Tactical action ${help('movement')}</h3><p>Activate a system, move fleets, invade planets, and produce units.</p><div class="buttons">${button('Activate selected system','tactical',{system:selected},'primary small')}${button('Choose on map','view',{view:'galaxy'},'ghost small')}</div></div><div class="card"><h3>02 / Strategic action ${help('strategyPrimary')}</h3><p>Use an unexhausted strategy card.</p><div class="buttons">${pl.strategies.map(c=>pl.used.includes(c)?`<span class="badge">${STRATEGIES[c].name} · used</span>`:button(c+' · '+STRATEGIES[c].name,'strategyForm',{card:c},'cyan small')).join('')}</div></div><div class="card"><h3>03 / Component action ${help('cards')}</h3><p>Use an implemented Action-timing card or faction action.</p><div class="buttons">${pl.faction==='sol'?button('Orbital Drop','orbitalForm',{},'small'):''}${button('View your hand','view',{view:'empire'},'ghost small')}</div></div></div><div class="buttons" style="margin-top:15px">${button('Trade','tradeForm',{},'small')}${help('trade')}${button('Pass for this round','engine',{type:'pass',args:{}},'ghost small')}</div>`;
 return panel('Current decision',q?.type?.startsWith('council')||q?.type==='agendaReveal'?'council':game.phase==='strategy'?'strategy':'action',html,esc(short(p)));
}
function archive(){return`<div class="layout equal"><div class="stack">${panel('Campaign archive','saves',`<p class="smalltext">Autosave stays in this browser. Download a backup to move your campaign between devices.</p><div class="buttons" style="margin:14px 0">${button('Download save','export',{},'primary')}${button('Import save','import',{},'ghost')}${button('Undo last decision','undo',{},'small')}${help('undo')}</div><div class="list">${slots().map(slot=>`<div class="card"><div class="row"><div><h3>${slot.id==='autosave'?'Autosave':'Checkpoint '+slot.id.at(-1)}</h3><small>${slot.savedAt?'Round '+slot.round+' · '+new Date(slot.savedAt).toLocaleString():slot.error?'Save unreadable':'Empty slot'}</small></div><div class="buttons">${slot.id!=='autosave'?button('Save','checkpoint',{slot:slot.id},'small'):''}${slot.savedAt?button('Load','loadSlot',{slot:slot.id},'ghost small'):''}</div></div></div>`).join('')}</div>`)}${panel('Automation controls','ai',`<p class="smalltext">Difficulty: ${esc(game.difficulty)}. Unfinished agenda effects pause for assisted review. AI errors pause instead of altering the rules to continue.</p><div class="buttons" style="margin-top:14px">${button(autoAI?'Pause AI':'Resume AI','autoAI',{},'cyan')}${button('New campaign','newMenu',{},'ghost')}</div>`)}</div><div class="stack">${panel('Rules and implementation','reference',`<div class="list"><a class="btn" href="${RULES_URL}" target="_blank" rel="noopener">Official base rules reference ↗</a><a class="btn" href="https://www.fantasyflightgames.com/product/twilight-imperium-fourth-edition/" target="_blank" rel="noopener">Fantasy Flight Games / TI4 ↗</a><a class="btn" href="docs/STATUS.md" target="_blank" rel="noopener">Detailed implementation checklist ↗</a>${button('Read implementation status','coverage',{},'ghost')}</div><div class="divider"></div><p class="smalltext">Original browser code and original vector artwork. Card and planet names are component references. No publisher endorsement is implied.</p>`)}${panel('Council records','council',game.laws.map(x=>`<div class="journal-entry"><h3>${esc(x.name)}</h3><p>${esc(x.note)}</p></div>`).join('')||'<div class="empty">No council records yet.</div>')}${panel('Faction catalogue','reference',`<div class="list">${Object.entries(FACTIONS).map(([id,f])=>`<div class="card row"><div><h3>${esc(f.factionName)}</h3><small>${f.commodities} commodities · ${f.complexity} complexity</small></div><span class="badge">${IMPLEMENTED_FACTIONS.includes(id)?'Enabled / partial':'Reference only'}</span></div>`).join('')}</div>`)}</div></div>`;}
function render(){if(map){camera=map.destroy();map=null;}if(!game){app.innerHTML=welcome();return;}let body='';if(view==='galaxy')body=`<div class="layout"><div class="stack">${mapPanel()}${panel('System intelligence','map',systemInfo())}</div><div class="stack">${currentOperation()}${tokensPanel(0)}${journal(5)}</div></div>`;if(view==='operations')body=`<div class="layout equal"><div class="stack">${currentOperation()}${tokensPanel(decision(game).player)}</div><div class="stack">${journal(12)}</div></div>`;if(view==='empire')body=empirePanel();if(view==='objectives')body=objectivesPage();if(view==='archive')body=archive();app.innerHTML=chrome(header()+body);const vp=document.querySelector('#galaxy-viewport');if(vp)map=mountGalaxy(vp,{snapshot:camera,onSelect:id=>{selected=id;render();},onChange:s=>camera=s});scheduleAI();}
const dialogStack=[];
function openDialog(heading,content,nested=false){clearTimeout(aiTimer);if(nested&&dialog.open)dialogStack.push([...dialog.childNodes]);else dialogStack.length=0;dialog.innerHTML=`<div class="dialog-head"><h2 id="dialog-title">${heading}</h2><button type="button" class="dialog-close" data-action="closeDialog" aria-label="Close dialog">×</button></div><div class="dialog-body">${content}</div>`;if(!dialog.open)dialog.showModal();dialog.scrollTop=0;}
function closeDialog(all=false){if(!all&&dialogStack.length){const nodes=dialogStack.pop();dialog.replaceChildren(...nodes);}else{dialogStack.length=0;dialog.close();scheduleAI();}}
function toast(text){const el=document.querySelector('#toast');el.textContent=text;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),5000);}
function showHelp(id){const h=HELP[id];if(!h)return;const g=guidance(game);openDialog(esc(h[0]),`<p>${esc(h[1])}</p>${game?`<div class="divider"></div><div class="eyebrow">Current situation</div><h3 style="margin:6px 0">${esc(g[0])}</h3><p class="smalltext">${esc(g[1])}</p>`:''}<div class="dialog-footer">Tap × or press Escape to close. The Archive contains the official rules and implementation checklist.</div>`,true);}
function coverage(){openDialog('Implementation status',`<div class="notice">This is a core-systems preview, not a complete digital implementation of every TI4 rule and asset.</div><div class="list"><div class="card"><h3>Implemented core loop</h3><p>Official preset maps for 3–6 players, strategy selection, all eight primary/secondary flows, command pools, movement and transport, d10 combat and casualty decisions, invasion, space-dock production, research prerequisites, public/status secret scoring, victory, local heuristic AI, portable saves, and touch controls.</p></div><div class="card"><h3>Partial or unfinished</h3><p>Six enabled factions have selected abilities; the other eleven are reference entries. The 80-card action deck is present, with seven Action-timing effects automated. Most response windows, promissory notes, flagship exceptions, several technologies, gravity-rift risk, and agenda-specific effects remain unfinished. Council voting currently needs assisted adjudication. Some card choices and payments are automated.</p></div><div class="card"><h3>Assets and scope</h3><p>Original scalable vector planets, ships and interface. Factual component names and values from the base game. Expansion content is excluded. This does not include complete physical card scans or miniature models.</p></div></div><div class="buttons"><a class="btn cyan" href="docs/STATUS.md" target="_blank" rel="noopener">Detailed coverage ↗</a><a class="btn ghost" href="${RULES_URL}" target="_blank" rel="noopener">Official rules ↗</a></div>`);}
function strategyForm(card,secondary=false){const p=decision(game).player,pl=game.players[p],c=STRATEGIES[card];let body='';
 if(card===1)body=`<div class="fields">${field('Additional tokens to buy',number('buy',0,Math.floor(available(game,p,'influence')/3)),'tokens')}${field('Add tokens to',select('pool',[['tactic','Tactic pool'],['strategy','Strategy pool'],['fleet','Fleet pool']]),'tokens')}</div><p class="form-note">${secondary?'':'Three free tokens go to tactic. '}Each additional token costs 3 influence. ${available(game,p,'influence')} influence is available.</p>`;
 if(card===2){const systems=[...new Set(ownedPlanets(game,p).filter(x=>x.system!=='0,0').map(x=>x.system))];body=`${secondary?'':field('Protect a system',select('system',systems.map(k=>[k,TILES[game.systems[k].tile].name])),'movement')}<div><div class="eyebrow">Ready up to two planets</div>${ownedPlanets(game,p).filter(x=>!x.ready).map(x=>check('readyPlanet',x.id,PLANETS[x.id].name)).join('')||'<p class="form-note">All your planets are ready.</p>'}</div>${pl.faction==='xxcha'?field('Peace Accords (optional)',select('accord',[['','Do not claim a planet'],...Object.values(game.planets).filter(x=>x.owner===null).map(x=>[x.id,PLANETS[x.id].name])]),'reference'):''}`;}
 if(card===3&&!secondary)body=field('Give the speaker token to',select('speaker',game.players.map((x,i)=>[i,short(i)]).filter(([i])=>i!==game.speaker),p!==game.speaker?p:undefined),'strategy')+'<p class="form-note">You draw two action cards. Agenda-deck inspection and arrangement are not automated yet.</p>';
 if(card===3&&secondary)body='<p class="form-note">Draw two action cards. Discard down to seven if needed.</p>';
 if(card===4)body=Array.from({length:secondary?1:2},(_,i)=>`<div class="fields">${field('Placement '+(i+1),select('structurePlanet'+i,planetChoices(p,true)),'production')}${field('Structure',select('structureType'+i,i===1?[['pds','PDS']]:[['pds','PDS'],['dock','Space dock']]),'production')}</div>`).join('');
 if(card===5)body=secondary?'<p class="form-note">Replenish commodities to your faction’s commodity value.</p>':`<div class="eyebrow">Allow free commodity replenishment</div>${game.players.map((x,i)=>i!==p?check('freePlayer',i,short(i),true):'').join('')}<p class="form-note">You gain 3 trade goods and replenish your commodities.</p>`;
 if(card===6){if(secondary)body=productionFields(p,pl.home);else body=`${field('Remove your activation token',select('remove',[['','No token to remove'],...Object.values(game.systems).filter(x=>x.tokens.includes(p)).map(x=>[x.key,TILES[x.tile].name])]),'movement')}<p class="form-note">One additional tactic token is gained. Full Warfare command-sheet redistribution is unfinished in this preview.</p>`;}
 if(card===7)body=`${field('Technology',select('tech',Object.entries(TECHS).filter(([id])=>canResearch(game,p,id)).map(([id,x])=>[id,x.name]),chooseTech(game,p)),'tech')}${!secondary||pl.faction==='jolnar'?field('Second technology (6 resources; optional)',select('tech2',[['','Do not research a second'],...Object.entries(TECHS).filter(([id,t])=>!pl.tech.includes(id)&&(!t.faction||t.faction===pl.faction)).map(([id,x])=>[id,x.name])]),'tech'):''}<p class="form-note">${secondary&&pl.faction!=='jolnar'?'The secondary costs 4 resources and a strategy token.':'The first technology is free.'} Planet-specialty skips and several technology effects are not yet automated.</p>`;
 if(card===8)body=secondary?'<p class="form-note">Draw one secret objective. You may have at most three secret objectives, including scored ones.</p>':`${field('Eligible public objective (optional)',select('objective',[['','Do not score a public objective'],...game.public.filter(id=>objectiveEligible(game,p,id)).map(id=>[id,OBJECTIVES[id].name])]),'objectives')}<p class="form-note">${game.planets.mr.owner===p?'You control Mecatol Rex: gain 1 VP.':'You do not control Mecatol Rex: draw one secret objective.'}</p>`;
 openDialog(`${card} / ${c.name}`,`<p class="smalltext" style="margin-bottom:18px">${esc(secondary?c.secondary:c.primary)}</p><form id="strategy-form" data-card="${card}" data-secondary="${secondary}" class="form-stack">${body}<div class="dialog-error"></div><button type="submit" class="btn primary">Resolve ${secondary?'secondary':'primary'} →</button></form>`);}
function tacticalForm(system){const p=decision(game).player,target=game.systems[system];if(!target)return;const sources=Object.values(game.systems).filter(x=>x.key!==system&&!x.tokens.includes(p)&&spaceUnits(game,x.key,p).length);openDialog('Activate / '+esc(TILES[target.tile].name),`<div class="notice">Spend one tactic token. Select ships from any number of unactivated source systems, and explicitly load infantry. Leave every source closed for a local activation without movement.</div><form id="tactical-form" data-system="${system}" class="form-stack">${sources.map(src=>{const us=src.ships.filter(u=>u.owner===p);return`<details><summary>${esc(TILES[src.tile].name)} · ${us.filter(u=>u.type!=='infantry').length} ships</summary><div data-source="${src.key}">${us.map(u=>{const v=unit(game,p,u.type);return check('move-'+src.key,u.id,UNIT_NAMES[u.type]+(u.damaged?' · damaged':''),false,`Move ${v.moveValue||'carried'} · capacity ${v.capacityValue}`);}).join('')}${TILES[src.tile].planets.filter(id=>game.planets[id].owner===p&&game.planets[id].ground.length).map(id=>field('Load infantry from '+esc(PLANETS[id].name),number('load-'+id,0,game.planets[id].ground.length),'transport')).join('')}</div></details>`;}).join('')||'<p class="form-note">No unactivated ships can move from another system.</p>'}${game.players[p].tech.includes('gd')?field('Gravity Drive: boost one ship',select('boost',[['','Do not use Gravity Drive'],...sources.flatMap(src=>src.ships.filter(u=>u.owner===p&&!['infantry','fighter'].includes(u.type)).map(u=>[u.id,UNIT_NAMES[u.type]+' / '+TILES[src.tile].name]))]),'tech'):''}<div class="dialog-error"></div><button type="submit" class="btn primary">Activate system →</button></form>`);}
function invasionForm(){const q=game.pending,p=q.player,sys=game.systems[q.system],cargo=sys.ships.filter(u=>u.owner===p&&u.type==='infantry').length,bombers=sys.ships.filter(u=>u.owner===p&&unit(game,p,u.type).bombard);openDialog('Invasion planning',`<p class="smalltext" style="margin-bottom:17px">${cargo} infantry are in transport. Choose a landing count on each planet. A bombarding ship can target only one planet.</p><form id="invasion-form" class="form-stack">${TILES[sys.tile].planets.map(id=>field(esc(PLANETS[id].name)+' / '+(game.planets[id].owner===null?'uncontrolled':esc(short(game.planets[id].owner))),number('land-'+id,0,cargo),'invasion')).join('')}${bombers.map(u=>field(UNIT_NAMES[u.type]+' bombardment target',select('bombard-'+u.id,[['','No bombardment'],...TILES[sys.tile].planets.filter(id=>game.planets[id].owner!==null&&game.planets[id].owner!==p).map(id=>[id,PLANETS[id].name])]),'invasion')).join('')}${TILES[sys.tile].planets.includes('mr')&&game.custodians?'<div class="notice">Landing on Mecatol Rex costs 6 influence and gains 1 VP for removing the custodians token.</div>':''}<div class="dialog-error"></div><button type="submit" class="btn primary">Resolve invasion →</button></form>`);}
function productionFields(p,system){const types=UNIT_TYPES.filter(t=>!['pds','spacedock'].includes(t)&&(t!=='warsun'||game.players[p].tech.includes('ws')));return`<p class="form-note">${available(game,p)} resources · production limit ${productionLimit(game,p,system)} units · fleet supply ${fleetLimit(game,p)}.</p><div class="list">${types.map(type=>{const v=unit(game,p,type);return`<div class="production-row"><label for="build-${type}">${UNIT_NAMES[type]}<small>${['infantry','fighter'].includes(type)?'2 for 1 resource':v.cost+' resources'} · Combat ${v.combatHitsOn<=10?v.combatHitsOn+'+':'—'}${v.moveValue?' · Move '+v.moveValue:''}${v.capacityValue?' · Carry '+v.capacityValue:''}</small></label><input id="build-${type}" type="number" name="build-${type}" min="0" max="${Math.min(25,LIMITS[type]-unitsOf(game,p,type).length)}" value="0" inputmode="numeric"></div>`;}).join('')}</div><p class="form-note" data-build-preview>Choose units. Payment is selected automatically and recorded in the journal.</p>`;}
function productionForm(){const q=game.pending;openDialog('Space-dock production',`<form id="production-form" class="form-stack">${productionFields(q.player,q.system)}<div class="dialog-error"></div><button type="submit" class="btn primary">Produce units →</button></form>`);}
function combatForm(){const q=game.pending,p=q.player;const destinations=Object.values(game.systems).filter(x=>{const sys=game.systems[q.system];const dist=(Math.abs(x.q-sys.q)+Math.abs(x.r-sys.r)+Math.abs(x.q+x.r-sys.q-sys.r))/2;return dist===1&&!x.ships.some(u=>u.owner!==p&&u.type!=='infantry')&&(spaceUnits(game,x.key,p).length||TILES[x.tile].planets.some(id=>game.planets[id].owner===p));});openDialog('Combat / Round '+q.round,`<form id="combat-form" class="form-stack"><p class="smalltext">Both forces roll simultaneously. You will assign incoming hits after the rolls.</p>${q.kind==='space'?field('Declare a retreat for your forces',select('retreat',[['','Stand and fight'],...destinations.map(x=>[x.key,TILES[x.tile].name])]),'retreat'):''}<div class="dialog-error"></div><button type="submit" class="btn primary">Roll combat dice →</button></form>`);}
function tradeForm(){const p=decision(game).player,partners=game.players.map((x,i)=>[i,short(i)]).filter(([i])=>i!==p&&(neighborPlayers(game,p,i)||game.players[p].faction==='hacan'||game.players[i].faction==='hacan'));openDialog('Negotiate a transaction',`<form id="trade-form" class="form-stack">${field('Trading partner',select('to',partners),'trade')}<div class="fields">${field('Your trade goods',number('give',0,game.players[p].tg),'economy')}${field('Your commodities',number('commodities',0,game.players[p].commodities),'trade')}${field('Their trade goods',number('receive',0,99),'economy')}${field('Their commodities',number('theirCommodities',0,6),'trade')}</div><p class="form-note">AI accepts an equal or favorable immediate resource exchange. Received commodities become trade goods.</p><div class="dialog-error"></div><button class="btn primary" type="submit">Offer transaction →</button></form>`);}
function cardForm(id){const p=decision(game).player,descriptions={mining_initiative:'Gain trade goods equal to the resource value of one planet you control.',industrial_initiative:'Gain 1 trade good for each industrial planet you control.',economic_initiative:'Ready your cultural planets.',f_deployment:'Place 3 infantry on a planet you control.',summit:'Gain 2 command tokens.',unexpected:'Remove one of your command tokens from the board.',messiah:'Place 1 infantry on each planet you control.',f_researched:'Spend 4 trade goods to research a technology.'};let fields='';if(id==='f_deployment'||id==='mining_initiative')fields=field('Planet',select('planet',planetChoices(p)),'invasion');if(id==='unexpected')fields=field('Remove a token',select('system',Object.values(game.systems).filter(x=>x.tokens.includes(p)).map(x=>[x.key,TILES[x.tile].name])),'tokens');if(id==='f_researched')fields=field('Technology',select('tech',Object.entries(TECHS).filter(([id])=>canResearch(game,p,id)).map(([id,t])=>[id,t.name])),'tech');openDialog(esc(ACTION_CATALOGUE[id].name),`<p class="smalltext" style="margin-bottom:16px">${descriptions[id]}</p><form id="card-form" data-card="${id}" class="form-stack">${fields}<div class="dialog-error"></div><button type="submit" class="btn primary">Play card →</button></form>`);}
function saveMenu(){openDialog('Campaign saves',`<p class="smalltext">Keep a downloaded backup to continue on a different device.</p><div class="buttons">${button('Download save','export',{},'primary')}${button('Import save','import',{},'ghost')}${button('Checkpoints & reference','view',{view:'archive'},'ghost')}</div><div class="dialog-footer">Every successful game action autosaves in this browser. ${help('saves')}</div>`);}
function scoreAction(id,secret){const p=decision(game).player;if(id==='fsn'){openDialog('Discard five action cards',`<form id="score-card-form" class="form-stack">${game.players[p].cards.map(c=>check('card',c,ACTION_CATALOGUE[c].name)).join('')}<div class="dialog-error"></div><button type="submit" class="btn primary">Discard five and score →</button></form>`);return;}act({type:'statusScore',args:{[secret?'secret':'public']:id}});}
function persist(){try{saveLocal(game);}catch(e){toast('Autosave unavailable. Download a backup from Archive.');}}
function act(action,isAI=false){if(!game)return;const previous=game;try{game=transact(game,{player:decision(game).player,...action});if(!isAI){history.push(previous);if(history.length>25)history.shift();}aiError='';persist();closeDialog(true);render();}catch(e){if(isAI){aiError=e.message;autoAI=false;render();}else{const box=dialog.open?dialog.querySelector('.dialog-error'):document.querySelector('#content .dialog-error');if(box)box.textContent=e.message;else toast(e.message);}return false;}return true;}
function isAITurn(){if(!game||game.winner!==null)return false;const d=decision(game);return!game.players[d.player].human&&d.type!=='councilResolve';}
function stepAI(){if(!isAITurn())return;try{const a=aiAction(game);if(!a){autoAI=false;render();return;}act(a,true);}catch(e){aiError=e.message;autoAI=false;render();}}
function scheduleAI(){clearTimeout(aiTimer);if(autoAI&&isAITurn()&&!dialog.open)aiTimer=setTimeout(stepAI,240);}
async function handle(action,args={}){
 if(action==='closeDialog'){closeDialog();return;}if(action==='coverage'){coverage();return;}if(action==='import'){document.querySelector('#import-file').click();return;}
 if(action==='resume'){try{const x=readLocal();if(!x)throw Error('No autosave found');game=x.state;selected=game.players[0].home;empire=0;view='galaxy';history=[];render();}catch(e){toast(e.message);}return;}
 if(action==='newMenu'){clearTimeout(aiTimer);openDialog('New campaign',`<p>A new campaign will replace the autosave. Download your current campaign or save a checkpoint first if you want to keep it.</p><div class="buttons">${button('Download current save','export',{},'ghost')}${button('Choose new campaign','welcome',{},'primary')}</div>`);return;}
 if(action==='welcome'){closeDialog(true);game=null;if(map){map.destroy();map=null;}camera=null;app.innerHTML=welcome();window.scrollTo({top:0});return;}
 if(!game)return;
 if(action==='view'){closeDialog(true);view=args.view;if(view==='empire')empire=0;render();window.scrollTo({top:0,behavior:'instant'});return;}
 if(action==='empire'){empire=Number(args.player);render();return;}
 if(action==='engine'){act({type:args.type,args:args.args||{}});return;}
 if(action==='strategyForm'){strategyForm(args.card,!!args.secondary);return;}if(action==='tactical'){tacticalForm(args.system);return;}if(action==='invasionForm'){invasionForm();return;}if(action==='productionForm'){productionForm();return;}if(action==='combatForm'){combatForm();return;}if(action==='tradeForm'){tradeForm();return;}if(action==='cardForm'){cardForm(args.card);return;}if(action==='saveMenu'){saveMenu();return;}if(action==='score'){scoreAction(args.id,args.secret);return;}
 if(action==='systemDetails'){openDialog('System intelligence',systemInfo());return;}
 if(action==='orbitalForm'){const p=decision(game).player;openDialog('Orbital Drop',`<p class="smalltext" style="margin-bottom:14px">Spend one strategy token to place two infantry on a planet you control.</p><form id="orbital-form" class="form-stack">${field('Planet',select('planet',planetChoices(p)),'invasion')}<div class="dialog-error"></div><button type="submit" class="btn primary">Perform Orbital Drop →</button></form>`);return;}
 if(action==='autoAI'){autoAI=!autoAI;aiError='';render();return;}if(action==='stepAI'){stepAI();return;}
 if(action==='export'){exportSave(game);toast('Save file downloaded.');return;}
 if(action==='checkpoint'){try{saveLocal(game,args.slot);toast('Checkpoint saved.');render();}catch(e){toast('Unable to save checkpoint: '+e.message);}return;}
 if(action==='loadSlot'){try{const x=readLocal(args.slot);if(!x)throw Error('That slot is empty');game=x.state;history=[];persist();render();toast('Campaign restored.');}catch(e){toast(e.message);}return;}
 if(action==='undo'){if(!history.length){toast('No local decision to undo.');return;}game=history.pop();aiError='';persist();render();toast('Returned to before your previous decision.');return;}
}
document.addEventListener('click',e=>{const h=e.target.closest('[data-help]');if(h){e.preventDefault();showHelp(h.dataset.help);return;}const b=e.target.closest('[data-action]');if(b){e.preventDefault();handle(b.dataset.action,b.dataset.args?JSON.parse(b.dataset.args):{});}});
dialog.addEventListener('cancel',e=>{e.preventDefault();closeDialog();});
document.addEventListener('change',e=>{if(e.target.id==='find-system'&&e.target.value){selected=e.target.value;render();map?.focus(game.systems[selected]);}});
document.addEventListener('input',e=>{if(e.target.name?.startsWith('build-')&&game){const form=e.target.closest('form'),p=decision(game).player,fd=new FormData(form),build=readBuild(fd),node=form.querySelector('[data-build-preview]');if(node)node.textContent=Object.values(build).reduce((a,b)=>a+b,0)+' units · '+buildCost(game,p,build)+' resources after discounts.';}});
const readBuild=fd=>Object.fromEntries(UNIT_TYPES.filter(t=>fd.has('build-'+t)).map(t=>[t,Number(fd.get('build-'+t))]));
document.addEventListener('submit',e=>{e.preventDefault();const form=e.target,fd=new FormData(form),get=k=>fd.get(k),n=k=>Number(get(k)||0);if(form.id==='new-game'){try{game=createGame({count:n('count'),faction:get('faction'),difficulty:get('difficulty'),target:n('target')});selected=game.players[0].home;empire=0;view='galaxy';history=[];camera=null;autoAI=true;aiError='';persist();render();window.scrollTo({top:0});}catch(error){toast(error.message);}return;}
 let action=null;
 if(form.id==='strategy-form'){const card=Number(form.dataset.card),secondary=form.dataset.secondary==='true',args={card,use:true};
  if(card===1){args.buy=n('buy');args.pool=get('pool');}if(card===2){args.system=get('system');args.planets=fd.getAll('readyPlanet');args.accord=get('accord')||undefined;}if(card===3)args.speaker=n('speaker');
  if(card===4)args.structures=[0,1].filter(i=>get('structurePlanet'+i)).map(i=>({planet:get('structurePlanet'+i),type:get('structureType'+i)}));if(card===5)args.free=fd.getAll('freePlayer').map(Number);
  if(card===6){args.remove=get('remove')||undefined;if(secondary)args.build=readBuild(fd);}if(card===7){args.tech=get('tech');if(get('tech2'))args.tech2=get('tech2');}if(card===8)args.objective=get('objective')||undefined;
  action={type:secondary?'secondary':'primary',args};
 }
 if(form.id==='tactical-form'){const moves=[];for(const src of Object.values(game.systems)){const units=fd.getAll('move-'+src.key);if(!units.length)continue;const load={};for(const id of TILES[src.tile].planets)if(n('load-'+id))load[id]=n('load-'+id);moves.push({from:src.key,units,load,boost:units.includes(get('boost'))?get('boost'):undefined});}action={type:'activate',args:{system:form.dataset.system,moves}};}
 if(form.id==='invasion-form'){const sys=game.systems[game.pending.system],lands=TILES[sys.tile].planets.map(planet=>({planet,count:n('land-'+planet),bombard:sys.ships.filter(u=>get('bombard-'+u.id)===planet).map(u=>u.id)}));action={type:'invade',args:{lands}};}
 if(form.id==='production-form')action={type:'produce',args:{build:readBuild(fd)}};
 if(form.id==='combat-form')action={type:'combatRoll',args:{retreats:get('retreat')?{[game.pending.player]:get('retreat')}:{}}};
 if(form.id==='redistribute-form')action={type:'redistribute',args:{tokens:{tactic:n('tactic'),fleet:n('fleet'),strategy:n('strategy')}}};
 if(form.id==='trade-form')action={type:'trade',args:{to:n('to'),give:n('give'),commodities:n('commodities'),receive:n('receive'),theirCommodities:n('theirCommodities')}};
 if(form.id==='orbital-form')action={type:'orbitalDrop',args:{planet:get('planet')}};
 if(form.id==='card-form')action={type:'playCard',args:{card:form.dataset.card,planet:get('planet'),system:get('system'),tech:get('tech')}};
 if(form.id==='score-card-form')action={type:'statusScore',args:{secret:'fsn',payment:{cards:fd.getAll('card')}}};
 if(form.id==='agenda-reveal')action={type:'agendaReveal',args:{agenda:get('agenda')}};
 if(form.id==='vote-form')action={type:'vote',args:{outcome:get('outcome'),planets:fd.getAll('votePlanet')}};
 if(form.id==='council-resolve')action={type:'councilResolve',args:{note:get('note')}};
 if(action)act(action);
});
document.querySelector('#import-file').addEventListener('change',async e=>{const file=e.target.files?.[0];if(!file)return;try{if(file.size>6_000_000)throw Error('Choose a save file smaller than 6 MB.');const state=importSave(await file.text());clearTimeout(aiTimer);game=state;history=[];camera=null;selected=game.players[0].home;empire=0;view='galaxy';aiError='';persist();closeDialog(true);render();toast('Save imported.');}catch(error){toast('Import failed: '+error.message);}e.target.value='';});
if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});
render();
